import{_ as d,c as e,aU as o,a as r}from"./chunks/framework.DIXiA2XH.js";const a="/assets/server001.5YYBQ0YD.png",c="/assets/server002.KDuX2-Mf.png",m=JSON.parse('{"title":"服务器监控","description":"","frontmatter":{},"headers":[],"relativePath":"note/server/linux/服务器监控.md","filePath":"note/server/linux/服务器监控.md","lastUpdated":1785508924000}'),s={name:"note/server/linux/服务器监控.md"};function i(h,t,l,n,p,u){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="服务器监控" tabindex="-1">服务器监控 <a class="header-anchor" href="#服务器监控" aria-label="Permalink to &quot;服务器监控&quot;">​</a></h1><h2 id="cpu" tabindex="-1">cpu <a class="header-anchor" href="#cpu" aria-label="Permalink to &quot;cpu&quot;">​</a></h2><p><code>top</code> 命令</p><p><img src="'+a+'" alt=""></p><p>如果想查看系统是几核的，可以再按 <code>1</code> 就可以显示出来详细的信息，说明该服务器cpu是2核的 <img src="'+c+'" alt=""></p><hr><h3 id="🖥️-cpu-使用情况-cpu-s" tabindex="-1">🖥️ CPU 使用情况（%Cpu(s)） <a class="header-anchor" href="#🖥️-cpu-使用情况-cpu-s" aria-label="Permalink to &quot;🖥️ CPU 使用情况（%Cpu(s)）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>指标名称</th><th>值 (%)</th><th>含义</th><th>用途/说明</th></tr></thead><tbody><tr><td><code>us</code> (user)</td><td>2.2</td><td>用户态进程占用的 CPU 时间</td><td>表示普通应用程序（非内核）消耗的 CPU，值高说明应用负载大</td></tr><tr><td><code>sy</code> (system)</td><td>1.0</td><td>内核态占用的 CPU 时间</td><td>系统调用、中断处理等内核操作所用 CPU，过高可能表示 I/O 或系统调用频繁</td></tr><tr><td><code>ni</code> (nice)</td><td>0.0</td><td>优先级被调整（<code>nice</code>）的用户进程 CPU 时间</td><td>通常较低，若高说明有大量低优先级任务在运行</td></tr><tr><td><code>id</code> (idle)</td><td>96.2</td><td>CPU 空闲时间</td><td>越高表示系统越空闲；接近 0 时系统可能过载</td></tr><tr><td><code>wa</code> (iowait)</td><td>0.0</td><td>CPU 等待 I/O 完成的时间</td><td>高值（&gt;10%）表示磁盘或存储性能瓶颈</td></tr><tr><td><code>hi</code> (hardware interrupts)</td><td>0.5</td><td>处理硬件中断的 CPU 时间</td><td>如网卡、磁盘控制器触发的中断，持续高可能需检查硬件</td></tr><tr><td><code>si</code> (software interrupts)</td><td>0.2</td><td>处理软件中断的 CPU 时间</td><td>由内核调度产生，一般较低</td></tr><tr><td><code>st</code> (steal time)</td><td>0.0</td><td>虚拟机被 Hypervisor “偷走” 的 CPU 时间</td><td>仅在虚拟化环境有意义；高值表示宿主机资源竞争激烈</td></tr></tbody></table><blockquote><p>✅ <strong>整体判断</strong>：CPU 负载极低（96.2% 空闲），系统非常轻载。</p></blockquote><hr><h3 id="💾-内存与-swap-使用情况-单位-mib" tabindex="-1">💾 内存与 Swap 使用情况（单位：MiB） <a class="header-anchor" href="#💾-内存与-swap-使用情况-单位-mib" aria-label="Permalink to &quot;💾 内存与 Swap 使用情况（单位：MiB）&quot;">​</a></h3><h4 id="物理内存-mem" tabindex="-1">物理内存（Mem） <a class="header-anchor" href="#物理内存-mem" aria-label="Permalink to &quot;物理内存（Mem）&quot;">​</a></h4><table tabindex="0"><thead><tr><th>指标名称</th><th>值 (MiB)</th><th>含义</th><th>用途/说明</th></tr></thead><tbody><tr><td><code>total</code></td><td>1889.0</td><td>系统总物理内存</td><td>≈ 1.84 GB</td></tr><tr><td><code>free</code></td><td>99.0</td><td>完全未使用的内存</td><td>Linux 会尽量利用内存做缓存，因此该值小是正常的</td></tr><tr><td><code>used</code></td><td>1353.8</td><td>已被进程使用的内存（不含缓存）</td><td>实际被应用程序分配的内存</td></tr><tr><td><code>buff/cache</code></td><td>436.2</td><td>用于缓冲区（buffer）和页缓存（cache）的内存</td><td>可被快速回收，提升 I/O 性能</td></tr><tr><td><code>avail Mem</code>（估算）</td><td>389.4</td><td>系统当前可分配给新进程的内存（含可回收缓存）</td><td><strong>比 <code>free</code> 更真实反映可用内存</strong></td></tr></tbody></table><h4 id="交换空间-swap" tabindex="-1">交换空间（Swap） <a class="header-anchor" href="#交换空间-swap" aria-label="Permalink to &quot;交换空间（Swap）&quot;">​</a></h4><table tabindex="0"><thead><tr><th>指标名称</th><th>值 (MiB)</th><th>含义</th><th>用途/说明</th></tr></thead><tbody><tr><td><code>total</code></td><td>1025.0</td><td>配置的 Swap 总量</td><td>≈ 1 GB，通常为磁盘上的交换分区或文件</td></tr><tr><td><code>free</code></td><td>363.4</td><td>未使用的 Swap 空间</td><td>—</td></tr><tr><td><code>used</code></td><td>661.6</td><td>已使用的 Swap 空间</td><td><strong>较高（占 64.5%）</strong>，表明物理内存不足，系统开始换出内存页到磁盘</td></tr><tr><td>—</td><td>—</td><td><strong>Swap 使用率</strong></td><td><code>661.6 / 1025 ≈ 64.5%</code></td></tr></tbody></table><blockquote><p>⚠️ <strong>关键提示</strong>：</p><ul><li>虽然 <code>free</code> 内存只有 99 MiB，但 <strong><code>avail Mem</code>（389.4 MiB）才是更准确的“可用内存”</strong>。</li><li><strong>Swap 使用量高（661.6 MiB）</strong> 是一个警告信号，可能引起性能下降（磁盘比内存慢得多）。建议： <ul><li>检查是否有内存泄漏的进程；</li><li>考虑增加物理内存；</li><li>调整 <code>vm.swappiness</code>（默认 60，可设为 10~30 减少 swap 倾向）。</li></ul></li></ul></blockquote><hr><p>你可以将以上内容直接复制到 <code>.md</code> 文件中使用。如果需要进一步分析具体进程的资源占用，也可以提供 <code>top</code> 中的进程列表部分。</p>',18)])])}const f=d(s,[["render",i]]);export{m as __pageData,f as default};
